    H,W=len(g),len(g[0]); seen=set(); out=[]
    for y in range(H):
        for x in range(W):
            if g[y][x]==val and (y,x) not in seen:
                st=[(y,x)]; seen.add((y,x)); cl=[(y,x)]
                while st:
                    a,b=st.pop()
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+dy,b+dx
                        if 0<=na<H and 0<=nb<W and g[na][nb]==val and (na,nb) not in seen:
                            seen.add((na,nb)); st.append((na,nb)); cl.append((na,nb))
                out.append(cl)
    return out
