import numpy as np
from collections import Counter, defaultdict
def comps2(i,v):
    H,W=i.shape; seen=set(); out=[]
    for y in range(H):
        for x in range(W):
            if i[y][x]==v and (y,x) not in seen:
                st=[(y,x)]; seen.add((y,x)); cl=[]
                while st:
                    p=st.pop(); cl.append(p)
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        q=(p[0]+dy,p[1]+dx)
                        if 0<=q[0]<H and 0<=q[1]<W and i[q[0]][q[1]]==v and q not in seen:
                            seen.add(q); st.append(q)
                out.append(cl)
    return out
def norm(cells):
    rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
    return tuple(sorted((r-min(rs),c-min(cs)) for r,c in cells))
def mindist(a,b):
    a=set(map(tuple,a)); b=set(map(tuple,b))
    return min(max(abs(p[0]-q[0]),abs(p[1]-q[1])) for p in a for q in b)
def f(inp):
    a=np.array(inp); H,W=a.shape
    cnti=Counter(int(x) for r in a.tolist() for x in r); bgc=cnti.most_common(1)[0][0]
    objs=[]
    for vv in sorted(set(int(x) for r in a.tolist() for x in r)-{bgc}):
        for cc in comps2(a,vv): objs.append((vv,tuple(sorted(cc))))
    colcomp=defaultdict(list)
    for vv,cc in objs: colcomp[vv].append(tuple(sorted(cc)))
    g2=defaultdict(list)
    for vv,cc in objs: g2[norm(cc)].append(vv)
    twgrp={k:v for k,v in g2.items() if len(v)>=2}
    singles=[(vv,colcomp[vv][0]) for vv,l in colcomp.items() if len(l)==1]
    tsets=[set(map(tuple,cc)) for kk,mem in twgrp.items() for vv,cc in mem]
    # singleton candidates: not touching any twin, closest to a twin group
    cand=[]
    for sv,sco in singles:
        so=set(map(tuple,sco))
        if any(mindist(so,t)==0 for t in tsets): continue
        dmin=min(min(mindist(so,set(map(tuple,mem))) for vv,cc in mem) for kk,mem in twgrp.items())
        cand.append((dmin,int(sv),len(sco)))
    _,svs,siz=min(cand)
    so=set(map(tuple,colcomp[svs][0]))
