import numpy as np
from collections import Counter, defaultdict
def comps2(a,v):
    H,W=a.shape; seen=set(); out=[]
    for y in range(H):
        for x in range(W):
            if a[y][x]==v and (y,x) not in seen:
                st=[(y,x)]; seen.add((y,x)); cl=[]
                while st:
                    p=st.pop(); cl.append(p)
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        q=(p[0]+dy,p[1]+dx)
                        if 0<=q[0]<H and 0<=q[1]<W and a[q[0]][q[1]]==v and q not in seen:
                            seen.add(q); st.append(q)
                out.append(cl)
    return out
def norm(cells):
    rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
    return tuple(sorted((r-min(rs),c-min(cs)) for r,c in cells))
def mindist(A,B):
    A={tuple(p) for p in A}; B={tuple(p) for p in B}
    return min(max(abs(p[0]-q[0]),abs(p[1]-q[1])) for p in A for q in B)
